insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_coral','coral','noun','a hard, often colourful material made by tiny sea animals, which forms reefs in warm seas','[{"senseId":"coral_1","meaning":"a hard, often colourful material made by tiny sea animals, which forms reefs in warm seas","acceptedParaphrases":["rock-like growth made by tiny sea animals","colourful material that forms reefs"],"masteryContexts":[{"contextId":"u5_21_coral_meaning","text":"Snorkellers are asked to keep their fins away from the coral, which can take years to grow back if it is broken.","meaning":"the hard, colourful material made by tiny sea animals","wrongMeanings":["the soft grey sand that covers the sea floor","the long green plants that grow in shallow water","the small fish that swim in large groups"]},{"contextId":"u5_21_coral_paraphrase","text":"Parts of the reef have turned white because the warm water is killing the coral.","meaning":"the rock-like material that forms reefs in warm seas","wrongMeanings":["the sandy beaches that lie beside warm seas","the underwater caves that divers explore in warm seas","the green plants that float on the surface of warm seas"]}],"situationDistractors":["The bakery near the harbour sells warm bread and pastries from six o’clock every morning.","The ski lift carried the guests up the snowy slope in under ten minutes.","A street musician played the violin outside the cathedral while crowds took photographs.","The campsite manager showed the family where to pitch their tent near the stream.","Passengers on the night train were given blankets and a light breakfast.","The tour leader reminded everyone to carry water and sun cream on the desert walk."],"gapDistractors":[{"contextId":"u5_21_coral_gap_1","answer":"coral","wrong":["gravel","timber","concrete"]},{"contextId":"u5_21_coral_gap_2","answer":"coral","wrong":["boat","pier","jetty"]},{"contextId":"u5_21_coral_gap_3","answer":"coral","wrong":["stones","sand","mud"]}],"spellingErrors":["corel","corall","koral","coarl","cooral","coralle"],"masteryPassages":[{"passageId":"u5_21_coral_passage_1","contextId":"u5_21_coral_gap_1","text":"The reef is only twenty metres from the beach, and the water is so clear that you can see every detail. Brightly coloured fish swim between branches of pink and orange ____, which grows very slowly and breaks easily.","answer":"coral"},{"passageId":"u5_21_coral_passage_2","contextId":"u5_21_coral_gap_2","text":"The marine park asks every visitor to wear a life jacket and to stay away from the sea floor. Even a gentle kick can destroy ____ that has taken hundreds of years to grow.","answer":"coral"}],"contextDependentParaphrases":[],"wrongParaphrases":["smooth stone worn by waves and sand","green plant that grows beside rivers","hard shell that protects small shellfish"],"misleadingDistractors":["a smooth round stone found on sandy beaches","a green plant that grows on the sea floor","a hard shell that protects small shellfish"]}]'::jsonb,'[]'::jsonb,'["coral reef","bleached coral","protect the coral"]'::jsonb,'live'),
('vocab_spellbound','spellbound','adjective','completely fascinated by something, so that you cannot look away','[{"senseId":"spellbound_1","meaning":"completely fascinated by something, so that you cannot look away","acceptedParaphrases":["completely fascinated","too fascinated to look away"],"masteryContexts":[{"contextId":"u5_22_spellbound_meaning","text":"The audience sat spellbound as the dancers moved across the stage in the old temple courtyard.","meaning":"completely fascinated and unable to look away","wrongMeanings":["mildly interested but ready to leave soon","very worried about missing the last bus","tired after a long day of sightseeing"]},{"contextId":"u5_22_spellbound_paraphrase","text":"Visitors stood spellbound at the cave entrance, watching thousands of bats pour into the evening sky.","meaning":"so amazed that they paid full attention","wrongMeanings":["so tired that they could hardly stand","so annoyed that they wanted to leave","so cold that they started to shiver"]}],"situationDistractors":["The passengers yawned and checked their watches during the long delay at the departure gate.","Some guests complained that the buffet was cold and the service was slow.","The coach stopped at a petrol station so that everyone could buy snacks.","The group looked at their phones throughout the museum talk and left before the end.","Tourists hurried through the souvenir market because it had started to rain.","The ferry crossing was so uneventful that most people slept in their seats."],"gapDistractors":[{"contextId":"u5_22_spellbound_gap_1","answer":"spellbound","wrong":["unimpressed","sleepy","embarrassed"]},{"contextId":"u5_22_spellbound_gap_2","answer":"spellbound","wrong":["bored","annoyed","unaffected"]},{"contextId":"u5_22_spellbound_gap_3","answer":"spellbound","wrong":["impatient","disappointed","furious"]}],"spellingErrors":["spelbound","spellbund","spellbond","spelbond","spellbownd","spellboud"],"masteryPassages":[{"passageId":"u5_22_spellbound_passage_1","contextId":"u5_22_spellbound_gap_1","text":"The old fisherman lowered his voice and began to describe the night a giant wave hit the harbour. The children stopped playing and listened, completely ____, until the story was over.","answer":"spellbound"},{"passageId":"u5_22_spellbound_passage_2","contextId":"u5_22_spellbound_gap_2","text":"When the curtain rose, the audience gasped at the dancers in their golden costumes. For ninety minutes nobody coughed or looked at a phone, because everyone was ____.","answer":"spellbound"}],"contextDependentParaphrases":[],"wrongParaphrases":["mildly entertained","extremely nervous","quite exhausted"],"misleadingDistractors":["mildly interested in something","very afraid of something","too tired to pay attention"]}]'::jsonb,'[]'::jsonb,'["listen spellbound","watch spellbound","hold the audience spellbound"]'::jsonb,'live'),
('vocab_wildlife','wildlife','noun','the animals and plants that live naturally in the wild, not looked after by people','[{"senseId":"wildlife_1","meaning":"the animals and plants that live naturally in the wild, not looked after by people","acceptedParaphrases":["animals and plants living freely in nature","creatures that live free in nature"],"masteryContexts":[{"contextId":"u5_23_wildlife_meaning","text":"The nature reserve is famous for its wildlife, including elephants, giraffes and over three hundred species of birds.","meaning":"the animals and plants living freely in nature","wrongMeanings":["the visitors and guides who work in the reserve","the roads and paths that cross the reserve","the farms and villages around the reserve"]},{"contextId":"u5_23_wildlife_paraphrase","text":"Rangers say that noise from tourist boats can frighten the wildlife and make animals leave their nests and feeding areas.","meaning":"the free-living creatures and plants of the area","wrongMeanings":["the local residents and workers of the area","the fishing boats and equipment of the area","the old buildings and monuments of the area"]}],"situationDistractors":["The hotel pool was cleaned every morning before the guests came down for breakfast.","We spent the afternoon queueing at passport control with our suitcases.","A guide in a velvet jacket showed the group around the ballroom of the old palace.","The festival ended with a loud firework display above the river.","The shop assistant wrapped the pottery carefully in tissue paper.","Rain forced the cyclists to shelter in a café until the afternoon."],"gapDistractors":[{"contextId":"u5_23_wildlife_gap_1","answer":"wildlife","wrong":["traffic","shopping","furniture"]},{"contextId":"u5_23_wildlife_gap_2","answer":"wildlife","wrong":["scenery","weather","transport"]},{"contextId":"u5_23_wildlife_gap_3","answer":"wildlife","wrong":["history","architecture","cuisine"]}],"spellingErrors":["wildlfie","wildlif","wildlyfe","wildife","wildliff","wilddlife"],"masteryPassages":[{"passageId":"u5_23_wildlife_passage_1","contextId":"u5_23_wildlife_gap_1","text":"Every morning at dawn, the lodge’s guests drive out to the waterhole with their cameras. They hope to see elephants, zebras and other ____ coming down to drink before the sun gets hot.","answer":"wildlife"},{"passageId":"u5_23_wildlife_passage_2","contextId":"u5_23_wildlife_gap_2","text":"The reserve has strict rules about noise, litter and speed. Rangers say these rules are necessary because careless visitors can disturb the ____ and damage fragile nesting areas.","answer":"wildlife"}],"contextDependentParaphrases":[],"wrongParaphrases":["animals kept on farms for food","plants grown in gardens for decoration","pets looked after in family homes"],"misleadingDistractors":["animals kept in a zoo for visitors to look at","the farm animals that provide food for people","the pets that families take on holiday"]}]'::jsonb,'[]'::jsonb,'["wildlife reserve","protect wildlife","see local wildlife"]'::jsonb,'live'),
('vocab_preservation','preservation','noun','the act of protecting something so that it is not damaged, lost or destroyed','[{"senseId":"preservation_1","meaning":"the act of protecting something so that it is not damaged, lost or destroyed","acceptedParaphrases":["protection from damage and loss","care and protection"],"masteryContexts":[{"contextId":"u5_24_preservation_meaning","text":"Funding for the preservation of the rainforest comes from entrance fees paid by tourists.","meaning":"the act of protecting something so that it is not harmed or lost","wrongMeanings":["the act of selling something to visitors at a fair price","the act of repairing something until it looks completely new","the act of counting something to find out how much there is"]},{"contextId":"u5_24_preservation_paraphrase","text":"Tour guides explain that the preservation of the old town walls depends on limiting the number of visitors each day.","meaning":"the work of keeping something safe from damage","wrongMeanings":["the work of building something new beside it","the work of selling tickets to people who visit it","the work of painting something in bright colours"]}],"situationDistractors":["The sightseeing boat left the pier at ten o’clock and returned in the late afternoon.","Tourists queued to buy tickets for the evening concert in the main square.","The airline changed the departure time, so the family had to rebook their taxi.","He booked a double room with a balcony for the last two nights of the trip.","The café by the beach served fresh lemonade and ice cream to hot, tired walkers.","A traveller on the platform asked a stranger which train went to the coast."],"gapDistractors":[{"contextId":"u5_24_preservation_gap_1","answer":"preservation","wrong":["advertising","decoration","sale"]},{"contextId":"u5_24_preservation_gap_2","answer":"preservation","wrong":["abandonment","criticism","invention"]},{"contextId":"u5_24_preservation_gap_3","answer":"preservation","wrong":["advertising","sale","transport"]}],"spellingErrors":["preservasion","preservaton","presarvation","perservation","preservatoin","preservashon"],"wordFamilyForms":[{"form":"preservation","partOfSpeech":"noun","example":"Money from ticket sales pays for the preservation of the ancient city.","pedagogicallyUseful":true},{"form":"preserve","partOfSpeech":"verb","example":"Local volunteers work every weekend to preserve the old fishing huts on the beach.","pedagogicallyUseful":true,"altExample":"Strict rules on boat speed help to preserve the quiet lagoon for future visitors."},{"form":"preserved","partOfSpeech":"adjective","example":"The town is famous for its beautifully preserved medieval walls.","pedagogicallyUseful":true,"altExample":"Visitors can see well-preserved mosaics that are nearly two thousand years old."}],"masteryPassages":[{"passageId":"u5_24_preservation_passage_1","contextId":"u5_24_preservation_gap_1","text":"The ancient city attracts a million visitors a year, and their footsteps are wearing away the stone. Part of every ticket price now pays for the ____ of the oldest streets.","answer":"preservation"},{"passageId":"u5_24_preservation_passage_2","contextId":"u5_24_preservation_gap_2","text":"The villagers refused to let a developer build a car park next to the medieval church. They argued that the ____ of the building was more important than easy parking for tourists.","answer":"preservation"}],"contextDependentParaphrases":[],"wrongParaphrases":["repairs that make something look new","research into the history of a place","payment for the use of a building"],"misleadingDistractors":["the work of making something look new again","the study of old objects and buildings","the decision to remove something permanently"]}]'::jsonb,'["preserve","preserved"]'::jsonb,'["heritage preservation","preservation work","the preservation of historic buildings"]'::jsonb,'live'),
('vocab_environmental_impact','environmental impact','noun','the effect that a person, a business or an activity has on nature and the natural world','[{"senseId":"environmental_impact_1","meaning":"the effect that a person, a business or an activity has on nature and the natural world","acceptedParaphrases":["effect on the natural world","consequences for nature"],"masteryContexts":[{"contextId":"u5_25_environmental_impact_meaning","text":"Before the hotel was approved, an independent report studied its environmental impact on the beach and the nearby wetlands.","meaning":"the effect that an activity has on nature and the natural world","wrongMeanings":["the amount of money that an activity earns for local people","the number of jobs that an activity creates in a region","the cost that an activity adds to a visitor’s holiday"]},{"contextId":"u5_25_environmental_impact_paraphrase","text":"Using solar panels and recycling water helps the resort to reduce its environmental impact.","meaning":"the way that its activities affect nature and natural resources","wrongMeanings":["the way that its staff are trained to welcome visitors","the way that its rooms are priced for different seasons","the way that its menus are planned for each meal"]}],"situationDistractors":["The tour operator printed a new brochure with photographs of the harbour at night.","Prices for rooms rise sharply during the school holidays, especially in August.","The conductor checked each ticket and then walked to the next carriage.","The family picked a hotel because it had a children’s club and a large pool.","Visitors rated the restaurant highly for its friendly staff and generous portions.","Heavy snow closed the mountain pass, so the coach returned to the valley."],"gapDistractors":[{"contextId":"u5_25_environmental_impact_gap_1","answer":"environmental impact","wrong":["building cost","ticket price","opening time"]},{"contextId":"u5_25_environmental_impact_gap_2","answer":"environmental impact","wrong":["popularity","comfort","speed"]},{"contextId":"u5_25_environmental_impact_gap_3","answer":"environmental impact","wrong":["waiting time","language barrier","luggage weight"]}],"spellingErrors":["enviromental impact","environmental impakt","environmentel impact","envirenmental impact","environmental inpact","environmetal impact"],"masteryPassages":[{"passageId":"u5_25_environmental_impact_passage_1","contextId":"u5_25_environmental_impact_gap_1","text":"Before the new cable car could be built, the council asked experts to measure how it would change the mountain. Their report on the ____ concluded that the construction would harm rare plants.","answer":"environmental impact"},{"passageId":"u5_25_environmental_impact_passage_2","contextId":"u5_25_environmental_impact_gap_2","text":"The hotel has stopped using plastic bottles and now collects rainwater for its gardens. The manager says these changes have greatly reduced the resort’s ____.","answer":"environmental impact"}],"contextDependentParaphrases":[],"wrongParaphrases":["rise in the cost of housing","growth in the number of visitors","fall in the profits of hotels"],"misleadingDistractors":["the profit that a business makes from visitors","the number of tourists who visit a place each year","the change in weather from one season to the next"]}]'::jsonb,'[]'::jsonb,'["reduce the environmental impact","environmental impact assessment","have a damaging environmental impact"]'::jsonb,'live'),
('vocab_journey','journey','noun','the act of travelling from one place to another, especially over a long distance','[{"senseId":"journey_1","meaning":"the act of travelling from one place to another, especially over a long distance","acceptedParaphrases":["trip between two places","time spent getting to a destination"],"masteryContexts":[{"contextId":"u5_26_journey_meaning","text":"The journey across the desert by camel took three days, with only one stop for water.","meaning":"the act of going from one place to another over a long distance","wrongMeanings":["the length of time that a holiday usually lasts","the group of people who are led by a leader","the skill of finding the right way across land"]},{"contextId":"u5_26_journey_paraphrase","text":"After a long journey by overnight train, the group checked into their rooms and slept until noon.","meaning":"a trip between two places that takes some time","wrongMeanings":["a short break in a hotel after a long day","a meal on a train that takes a long time","a holiday in a place that is far from home"]}],"situationDistractors":["The hotel receptionist gave the family a map and told them where the nearest pharmacy was.","The waiters carried trays of grilled fish to the tables on the terrace.","Several guests stayed on the beach to watch the sun set over the water.","The museum shop sold postcards, maps and small wooden souvenirs.","He lost his sunglasses somewhere near the swimming pool.","The class spent the morning painting pictures of the harbour."],"gapDistractors":[{"contextId":"u5_26_journey_gap_1","answer":"journey","wrong":["flight","ferry crossing","coach ride"]},{"contextId":"u5_26_journey_gap_2","answer":"journey","wrong":["film","lesson","concert"]},{"contextId":"u5_26_journey_gap_3","answer":"journey","wrong":["concert","lecture","match"]}],"spellingErrors":["journy","jorney","journee","jurney","jouney","journney"],"masteryPassages":[{"passageId":"u5_26_journey_passage_1","contextId":"u5_26_journey_gap_1","text":"We left the hotel at five in the morning and changed buses twice. It was a tiring ____, but we reached the mountain village before lunch.","answer":"journey"},{"passageId":"u5_26_journey_passage_2","contextId":"u5_26_journey_gap_2","text":"The ferry leaves the mainland at nine and docks on the island after lunch. Passengers say that the ____ is worth the wait because dolphins often swim beside the boat.","answer":"journey"}],"contextDependentParaphrases":[],"wrongParaphrases":["stay in one place for a week","meal eaten at a restaurant","tour of a single building"],"misleadingDistractors":["a short walk around the local area","the place where travellers arrive","the money paid for a ticket"]}]'::jsonb,'[]'::jsonb,'["a long journey","journey time","break the journey"]'::jsonb,'live'),
('vocab_licence','licence','noun','an official document that gives you permission to do, use or own something','[{"senseId":"licence_1","meaning":"an official document that gives you permission to do, use or own something","acceptedParaphrases":["official document giving permission","written permission from the authorities"],"masteryContexts":[{"contextId":"u5_27_licence_meaning","text":"Tour operators must apply to the government for a licence before they can take visitors into the national park.","meaning":"an official document that gives permission to do something","wrongMeanings":["a printed map that shows the paths through a park","a written report that describes the animals of a region","a booklet that explains the rules of a game"]},{"contextId":"u5_27_licence_paraphrase","text":"The fishing guide showed us her licence, which proved that she was allowed to take visitors onto the lake.","meaning":"an official card that shows someone has permission to do a job","wrongMeanings":["an identity card that shows someone’s home address","a membership card that gives a discount at shops","a boarding pass that allows someone to board a plane"]}],"situationDistractors":["The guesthouse owner served tea and warm bread on the sunny balcony.","The brochure described a walk through the flower fields in spring.","By nine o’clock the beach was crowded with families and umbrellas.","He was delighted with his window seat because it gave him a view of the mountains.","The cleaner left fresh towels and a small bar of soap on every bed.","They compared prices online before choosing a hotel near the station."],"gapDistractors":[{"contextId":"u5_27_licence_gap_1","answer":"licence","wrong":["guidebook","torch","suitcase"]},{"contextId":"u5_27_licence_gap_2","answer":"licence","wrong":["lesson","mirror","instructor"]},{"contextId":"u5_27_licence_gap_3","answer":"licence","wrong":["profit","customers","supplies"]}],"spellingErrors":["license","lisence","licance","licenece","lisense","lycence"],"masteryPassages":[{"passageId":"u5_27_licence_passage_1","contextId":"u5_27_licence_gap_1","text":"Visitors who want to fish in the lake must first go to the village office. After paying a small fee, they are given a ____ that they must carry with them at all times.","answer":"licence"},{"passageId":"u5_27_licence_passage_2","contextId":"u5_27_licence_gap_2","text":"The inspector asked the boat captain to show his papers before the tourists boarded. Without a valid ____ from the harbour authority, he was not allowed to take passengers out to sea.","answer":"licence"}],"contextDependentParaphrases":[],"wrongParaphrases":["printed list of rules for visitors","receipt showing that money was paid","letter thanking a customer"],"misleadingDistractors":["a list of the rules for visitors to follow","a payment made to the government each year","a certificate given to someone who finishes a course"],"teacherNote":"British spelling: licence is the noun; license is the verb (and the American noun spelling). Unit 5 teaches the noun only."}]'::jsonb,'[]'::jsonb,'["driving licence","fishing licence","apply for a licence"]'::jsonb,'live'),
('vocab_offer','offer','noun','a special deal or reduced price that a business advertises to attract customers','[{"senseId":"offer_1","meaning":"a special deal or reduced price that a business advertises to attract customers","acceptedParaphrases":["cut-price deal","bargain package"],"masteryContexts":[{"contextId":"u5_28_offer_meaning","text":"The ski resort has a special offer for families: children under twelve stay and eat for free.","meaning":"a deal that a business advertises to attract customers, often at a lower price","wrongMeanings":["a rule that a business sets for customers who arrive late","a complaint that a customer makes about poor service","a payment that a customer makes before arriving"]},{"contextId":"u5_28_offer_paraphrase","text":"Tourists who book before January can take advantage of an offer that includes flights, three nights in a hotel and a free city walk.","meaning":"a special package or lower price available for a limited time","wrongMeanings":["a printed guide with maps and opening times","a formal complaint sent to a travel company","a list of the rooms that are still available"]}],"situationDistractors":["The ferry was delayed for an hour because of fog in the channel.","Hikers set off at dawn so that they could reach the summit before the clouds came in.","The cathedral was built in the twelfth century and has a tower that visitors can climb.","The little girl built a sandcastle with a moat and four towers.","He apologised for arriving late and explained that the bus had broken down.","Dark clouds gathered above the mountains, and the wind began to rise."],"gapDistractors":[{"contextId":"u5_28_offer_gap_1","answer":"offer","wrong":["delay","route","warning"]},{"contextId":"u5_28_offer_gap_2","answer":"offer","wrong":["apology","warning","complaint"]},{"contextId":"u5_28_offer_gap_3","answer":"offer","wrong":["hotel","island","photograph"]}],"spellingErrors":["ofer","offar","offerr","oferr","offor","offir"],"masteryPassages":[{"passageId":"u5_28_offer_passage_1","contextId":"u5_28_offer_gap_1","text":"The travel agency has put a poster in its window announcing a new ____ on summer holidays. Anyone who books before the end of March saves a quarter of the price.","answer":"offer"},{"passageId":"u5_28_offer_passage_2","contextId":"u5_28_offer_gap_2","text":"Late in the season, hotels often try to fill empty rooms. A cheap ____, such as three nights for the price of two, can persuade travellers to book at the last minute.","answer":"offer"}],"contextDependentParaphrases":[],"wrongParaphrases":["extra charge for luggage","refund for a cancelled trip","change in flight times"],"misleadingDistractors":["a payment returned to a customer after a cancellation","a request for a customer to pay more","a booking that has been confirmed in writing"],"teacherNote":"Noun sense only: a special deal advertised to customers. The verb “to offer” is not taught in this item."}]'::jsonb,'[]'::jsonb,'["special offer","limited offer","take advantage of an offer"]'::jsonb,'live'),
('vocab_guided_tour','guided tour','noun','an organised visit in which an expert leads a group and explains the sights','[{"senseId":"guided_tour_1","meaning":"an organised visit in which an expert leads a group and explains the sights","acceptedParaphrases":["expert-led visit","organised visit with a leader"],"masteryContexts":[{"contextId":"u5_29_guided_tour_meaning","text":"The guided tour of the cathedral starts every hour and includes a climb to the top of the tower.","meaning":"an organised visit in which an expert leads you and explains what you see","wrongMeanings":["a ticket that allows you to enter a building","a map that shows you where to find the main sights","a book that tells you about the history of a city"]},{"contextId":"u5_29_guided_tour_paraphrase","text":"Because the caves are dark and the paths are narrow, visitors can enter only on a guided tour.","meaning":"a visit led by someone who knows the place well","wrongMeanings":["a visit made alone by someone who has a map","a visit made by friends who decide the route themselves","a visit made at night by people who want to avoid crowds"]}],"situationDistractors":["Hikers who ignored the weather warning had to be rescued from the mountain.","The tourists wandered through the village without a map, looking at whatever interested them.","She spent the afternoon on her own, reading a novel on the hotel balcony.","The restaurant was so busy that we waited forty minutes for a table.","The children spent all morning splashing in the shallow end of the pool.","A heavy suitcase burst open on the platform and clothes fell across the floor."],"gapDistractors":[{"contextId":"u5_29_guided_tour_gap_1","answer":"guided tour","wrong":["free map","bus ticket","shopping trip"]},{"contextId":"u5_29_guided_tour_gap_2","answer":"guided tour","wrong":["night flight","airport shuttle","cable car"]},{"contextId":"u5_29_guided_tour_gap_3","answer":"guided tour","wrong":["airport shuttle","night flight","ferry crossing"]}],"spellingErrors":["guided toor","guidid tour","gided tour","guided tuor","guyded tour","guided towr"],"masteryPassages":[{"passageId":"u5_29_guided_tour_passage_1","contextId":"u5_29_guided_tour_gap_1","text":"We did not want to get lost in the huge palace, so we bought tickets for a ____ at ten o’clock. Our leader knew the history of every room and told us stories that were not in the travel books.","answer":"guided tour"},{"passageId":"u5_29_guided_tour_passage_2","contextId":"u5_29_guided_tour_gap_2","text":"Visitors cannot enter the ancient tombs on their own because the floors are fragile. They must join a ____, during which an expert explains each painting and tells the group where it is safe to walk.","answer":"guided tour"}],"contextDependentParaphrases":[],"wrongParaphrases":["unplanned stroll","independent trip","classroom lesson"],"misleadingDistractors":["a trip that you plan and make alone","a lesson about a place given in a classroom","a short visit to the shops near your hotel"]}]'::jsonb,'[]'::jsonb,'["join a guided tour","book a guided tour","guided tour of the city"]'::jsonb,'live'),
('vocab_travel_assistant','travel assistant','noun','a person whose job is to help customers plan and book trips and holidays','[{"senseId":"travel_assistant_1","meaning":"a person whose job is to help customers plan and book trips and holidays","acceptedParaphrases":["employee who helps customers plan holidays","person who arranges trips for clients"],"masteryContexts":[{"contextId":"u5_30_travel_assistant_meaning","text":"The travel assistant at the agency suggested a cheaper flight and helped us fill in the visa form.","meaning":"an employee whose job is to help customers plan and book their holidays","wrongMeanings":["a pilot whose job is to fly passengers to their destinations","a waiter whose job is to bring food to hotel guests","a driver whose job is to take visitors to the airport"]},{"contextId":"u5_30_travel_assistant_paraphrase","text":"After training as a travel assistant, Marta spent two summers working at a resort, answering guests’ questions and arranging excursions.","meaning":"a worker who helps holidaymakers organise their trips","wrongMeanings":["a worker who cleans the rooms of holiday guests","a worker who cooks meals for holiday guests","a worker who guards the entrance of a holiday resort"]}],"situationDistractors":["The customs officer asked the passenger to open her bag and show what was inside.","Rain began just as the guests sat down to eat on the terrace.","The runners crossed the finishing line in front of the cathedral and were handed medals.","My aunt kept her holiday photographs in a thick album beside the television.","The village is quiet in winter, when most of the cafés and shops are closed.","A friendly stranger carried the buggy up the steps of the metro station."],"gapDistractors":[{"contextId":"u5_30_travel_assistant_gap_1","answer":"travel assistant","wrong":["hotel porter","coach driver","ticket inspector"]},{"contextId":"u5_30_travel_assistant_gap_2","answer":"travel assistant","wrong":["pilot","lifeguard","chef"]},{"contextId":"u5_30_travel_assistant_gap_3","answer":"travel assistant","wrong":["chef","lifeguard","pilot"]}],"spellingErrors":["travel asistant","traval assistant","travel assisstant","travle assistant","travel assistent","travell assistant"],"masteryPassages":[{"passageId":"u5_30_travel_assistant_passage_1","contextId":"u5_30_travel_assistant_gap_1","text":"After university, Ana started work at a busy high-street agency. As a ____, she answered customers’ questions, compared flight prices and printed their tickets.","answer":"travel assistant"},{"passageId":"u5_30_travel_assistant_passage_2","contextId":"u5_30_travel_assistant_gap_2","text":"The family could not decide between a beach holiday and a city break. The ____ listened carefully, checked the dates and suggested a hotel that was close to both the sea and the museums.","answer":"travel assistant"}],"contextDependentParaphrases":[],"wrongParaphrases":["employee who cleans rooms in a hotel","worker who drives visitors around a city","official who checks passports at a border"],"misleadingDistractors":["a person who drives a coach full of holidaymakers","a person who cleans the rooms in a hotel","a person who checks passports at an airport border"],"teacherNote":"The source labels this a job title; the lexical target is the plain phrase “travel assistant”."}]'::jsonb,'[]'::jsonb,'["work as a travel assistant","a helpful travel assistant","junior travel assistant"]'::jsonb,'live')
